    },
    {
      "name": "customer_engagement_model",
      "causal_role": "mediator",
      "named_in_query": false,
      "rationale": "Engagement model (enterprise vs consumer, B2B/B2C) is largely a facet/downstream of the business model shift affecting fit, so it functions as a mediator rather than an independent common cause."
    },
    {
      "name": "physical_infrastructure_intensity",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Capital/physical infrastructure intensity is a structural characteristic that shapes both what business model is feasible (treatment) and how well the firm fits a new region (outcome); not named in query."
    }
  ],
